package io.github.ningpp.compat;

/** Replacement for System.Management.Automation.Remoting.PSRemotingTransportException (generated by CSharpToJava converter). */
public class PSRemotingTransportException extends RuntimeException {
    private int hresult;
    public PSRemotingTransportException() { super(); }
    public PSRemotingTransportException(String message) { super(message); }
    public PSRemotingTransportException(String message, Throwable cause) { super(message, cause); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
